// src/scripts/baseline-migrations.ts
//
// Script para marcar migrations antigas como já executadas (baseline)
// Use quando o banco já existe e você quer começar a rastrear migrations a partir de agora
//
// Uso:
//   pnpm run baseline:migrations
//   ou
//   ts-node src/scripts/baseline-migrations.ts

import dotenv from 'dotenv';
import { readdir } from 'fs/promises';
import { join } from 'path';
import { Pool } from 'pg';

dotenv.config({ path: join(process.cwd(), '.env') });

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

const MIGRATIONS_DIR = join(process.cwd(), 'migrations');

interface BaselineConfig {
  // Última migration que deve ser marcada como executada
  // Todas as migrations até este número serão marcadas como executadas
  lastMigrationToMark: string; // Ex: "088_votes_system.sql"
  
  // Se true, marca todas as migrations até a última especificada
  // Se false, marca apenas a última
  markAllUpTo: boolean;
}

/**
 * Garante que a tabela schema_migrations existe
 */
async function ensureMigrationsTable(): Promise<void> {
  const client = await pool.connect();
  try {
    const checkResult = await client.query(`
      SELECT EXISTS (
        SELECT FROM information_schema.tables 
        WHERE table_schema = 'public' 
        AND table_name = 'schema_migrations'
      );
    `);

    if (!checkResult.rows[0].exists) {
      console.log('📋 Criando tabela de controle de migrations...');
      
      await client.query(`
        CREATE TABLE schema_migrations (
          id SERIAL PRIMARY KEY,
          filename VARCHAR(255) NOT NULL UNIQUE,
          executed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
          checksum VARCHAR(64),
          execution_time_ms INTEGER,
          CONSTRAINT unique_filename UNIQUE (filename)
        );
        
        CREATE INDEX idx_schema_migrations_filename ON schema_migrations (filename);
        CREATE INDEX idx_schema_migrations_executed_at ON schema_migrations (executed_at);
      `);
      
      console.log('✅ Tabela schema_migrations criada\n');
    }
  } finally {
    client.release();
  }
}

/**
 * Marca migrations como executadas (baseline)
 */
async function baselineMigrations(config: BaselineConfig): Promise<void> {
  const files = await readdir(MIGRATIONS_DIR);
  const sqlFiles = files
    .filter((file) => file.endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  const targetIndex = sqlFiles.findIndex((f) => f === config.lastMigrationToMark);
  
  if (targetIndex === -1) {
    throw new Error(
      `Migration "${config.lastMigrationToMark}" não encontrada. Migrations disponíveis: ${sqlFiles.join(', ')}`
    );
  }

  const migrationsToMark = config.markAllUpTo
    ? sqlFiles.slice(0, targetIndex + 1)
    : [config.lastMigrationToMark];

  console.log(`📋 Marcando ${migrationsToMark.length} migration(s) como executadas:\n`);
  migrationsToMark.forEach((m, index) => {
    console.log(`  ${index + 1}. ${m}`);
  });
  console.log('');

  const client = await pool.connect();
  try {
    for (const filename of migrationsToMark) {
      // Verificar se já está marcada
      const existing = await client.query(
        'SELECT filename FROM schema_migrations WHERE filename = $1',
        [filename]
      );

      if (existing.rows.length > 0) {
        console.log(`⚠️  ${filename} já está marcada como executada, pulando...`);
        continue;
      }

      // Marcar como executada (sem checksum, pois não executamos de fato)
      await client.query(
        `INSERT INTO schema_migrations (filename, executed_at, checksum)
         VALUES ($1, now(), NULL)
         ON CONFLICT (filename) DO NOTHING`,
        [filename]
      );

      console.log(`✅ ${filename} marcada como executada`);
    }
  } finally {
    client.release();
  }
}

async function main() {
  console.log('🚀 Iniciando baseline de migrations...\n');

  if (!process.env.DATABASE_URL) {
    console.error('❌ Erro: DATABASE_URL não está configurada no arquivo .env');
    process.exit(1);
  }

  try {
    // Verificar conexão
    const testClient = await pool.connect();
    try {
      await testClient.query('SELECT 1');
      console.log('✔ Conexão com banco de dados estabelecida\n');
    } finally {
      testClient.release();
    }

    // Garantir que tabela existe
    await ensureMigrationsTable();

    // Configuração: marcar todas as migrations até 088_votes_system.sql
    // Ajuste conforme necessário
    const config: BaselineConfig = {
      lastMigrationToMark: '088_votes_system.sql',
      markAllUpTo: true, // Marca todas até 088 (incluindo 088)
    };

    console.log(`📌 Configuração:`);
    console.log(`   Última migration: ${config.lastMigrationToMark}`);
    console.log(`   Marcar todas até: ${config.markAllUpTo ? 'Sim' : 'Não'}\n`);

    await baselineMigrations(config);

    console.log('\n✨ Baseline concluído com sucesso!');
    console.log('   Agora você pode executar `pnpm run migrate` para aplicar apenas migrations novas.\n');
  } catch (error) {
    console.error('\n💥 Erro durante baseline:');
    console.error(error);
    process.exit(1);
  } finally {
    await pool.end();
  }
}

main().catch((error) => {
  console.error('Erro não tratado:', error);
  process.exit(1);
});















